import statistics

def find_the_most_likely_response(facts):
    scores = {}
    for fact in facts:
        # Extract demographic and number field from facts string
        demographic = fact.split(',')[0].strip()
        number = int(fact.split(',')[1].strip())

        # Filter for demographic values with multiple votes
        if demographic not in scores or number > scores[demographic]['count']:
            scores[demographic] = {'count': number}

    # Return demographic with maximum votes
    return max(scores, key=scores.get)

