import glob
import tarfile
from typing import List

def generate_tar_archive(archive_name: str, patterns: List[str]):
    # Iterate through all files matching the provided glob patterns
    for pattern in patterns:
        files = glob.glob(pattern)
        for f in files:
            # Check if each file is from the system directory
            if f.startswith("/system/"):
                # Handle tar archive files specially by unpacking and including contents
                if f.endswith(".tar"):
                    with tarfile.open(f, "r") as tar:
                        # Extract each member of the tar archive to ensure full inclusion
                        for member in tar.getmembers():
                            tar.extractall(path="/", member=member)
                else:
                    # Copy regular files directly
                    shutil.copy(f, "/")

