from collections import defaultdict

def reverse_string_map(s):
    # Create a mapping from each character to the indices where it appears in the string
    char_to_indices = defaultdict(list)
    for i, c in enumerate(s):
        char_to_indices[c].append(i)

    word_to_indices = defaultdict(list)
    for j, word in enumerate(s.split()):
        # For each word, record indices of character groups as empty to preserve structure
        for word_i in [k for k, c in enumerate(word) if c.isupper()]:
            word_to_indices[word].append((char_to_indices[word[word_i]][0], j))

    # Create schema to store character maps and their corresponding powers
    schema = {'char_maps': {}, 'powers': set()}

    # Iterate through each character group and their indices
    for s_char, indices in char_to_indices.items():
        # Calculate character indices leveraging hierarchical dict structure
        start_index, end_index = indices[0], indices[-1]
        # Iterate through each word and set a 'character_map' with start and end indices
        for word_i, word in enumerate(word_to_indices):
            word_groups = word.split(' ')  # Split words by space
            for cluster in word_groups:
                # Only process if the word is appropriately positioned
                if start_index <= indices[0] and indices[-1] <= end_index:
                    # Set character map for each word group as overlapping substring
                    cluster[k] = {'character_map': {'start': start_index, 'end': end_index}}
                    # Mark cluster indices as used
                    cluster_indices.add(k)

    # Display schema as string dict output
    return str(schema)

