class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class Linkedlist:
    def __init__(self):
        self.head = None

    def insert(self, data):
        if self.head is None:
            self.head = Node(data)
        else:
            newNode = Node(data)
            newNode.next = self.head
            self.head = newNode

    # Utility to traverse and reassign to head, then look one node ahead
    def remove(self, key):
        # Skip head nodes matching the key value directly
        while self.head and self.head.data == key:
            self.head = self.head.next

        # Traverse remaining list, compare each node to key, and adjust pointers
        current = self.head
        while current:
            if current.data == key:
                # Skip invalid nodes by reassigning parent's next
                nextNode = current.next
                while nextNode and nextNode.data == key:
                    nextNode = nextNode.next
                # Point parent to corrected next pointer
                current.next = nextNode
            current = current.next

    def printList(self):
        link = self.head
        while link:
            print(link.data, end=" ")
            link = link.next
        print()

if __name__ == "__main__":
    linkedlist = Linkedlist()
    # Accept input list to populate the linked list
    input_list = input().strip().split()
    for data in input_list:
        linkedlist.insert(data)
    # Accept removal specification and execute
    removal = input().strip()
    linkedlist.remove(removal)
    # Display modified list
    linkedlist.printList()

