def print_letter_count(text):
    # Count the frequency of each letter in the input string
    letters = {}
    for letter in text:
        if letter not in letters:
            letters[letter] = 1
        else:
            letters[letter] += 1

    # Sort the dictionary by the number of occurrences in descending order
    for key in sorted(letters, key=letters.get, reverse=True):
        print(f"{key}: {letters[key]}")

